UPDATE sys_tenant_package SET package_code = #{packageCode}, package_name = #{packageName}, menu_ids = #{menuIds}, max_users = #{maxUsers},
    max_storage_mb = #{maxStorageMb}, enabled_modules = #{enabledModules}, price = #{price}, billing_cycle = #{billingCycle},
    sort_no = #{sortNo}, status = #{status}, remark = #{remark}, version = version + 1, update_by = #{updateBy}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND package_id = #{packageId} AND deleted = 0 AND version = #{version}

UPDATE sys_tenant SET package_id = #{entity.packageId}, package_version = #{entity.packageVersion},
    package_override = #{entity.packageOverride}, effective_menu_ids = #{entity.effectiveMenuIds},
    user_limit = #{entity.userLimit}, storage_limit = #{entity.storageLimit}, version = version + 1,
    update_by = #{entity.updateBy}, update_time = #{entity.updateTime}
WHERE tenant_id = #{entity.tenantId} AND deleted = 0 AND version = #{expectedVersion} AND package_id = #{expectedPackageId}

UPDATE sys_tenant SET tenant_code = #{tenantCode}, tenant_name = #{tenantName}, contact_name = #{contactName},
    contact_phone = #{contactPhone}, contact_email = #{contactEmail}, allowed_email_domains = #{allowedEmailDomains},
    domain = #{domain}, status = #{status}, expire_time = #{expireTime}, user_limit = #{userLimit}, storage_limit = #{storageLimit},
    package_id = #{packageId}, package_version = #{packageVersion}, package_override = #{packageOverride}, effective_menu_ids = #{effectiveMenuIds},
    version = version + 1, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}
WHERE tenant_id = #{tenantId} AND deleted = 0 AND version = #{version}

UPDATE sys_tenant_package_sync_item SET status = #{status}, error_code = #{errorCode}, applied_time = #{appliedTime},
    update_by = #{updateBy}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND sync_id = #{syncId} AND item_id = #{itemId} AND status != 'APPLIED'
